    int head[N], total, current[N], dist[N], u, v, s, t, source, sink;
    struct Edge {
        int v, next, capacity;
    } edges[111111];

    void add_edge(int u, int v, int cap) {
        edges[total] = {v, head[u], cap};
        head[u] = total++;
        edges[total] = {u, head[v], 0};
        head[v] = total++;
    }

    void initialize() {
        memset(head, -1, sizeof head);
        total = 0;
    }

    bool build_bfs() {
        memset(dist, -1, sizeof dist);
        memcpy(current, head, sizeof head);
        dist[source] = 0;
        queue<int> q;
        q.push(source);
        while(!q.empty()) {
            int u = q.front(); q.pop();
            for(int i = head[u]; i != -1; i = edges[i].next) {
                v = edges[i].v;
                if(dist[v] == -1 && edges[i].capacity > 0) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        return dist[sink] != -1;
    }

    int send_flow(int u, int flow) {
        if(u == sink) return flow;
        int total_flow = 0, pushed;
        for(int &i = current[u]; i != -1; i = edges[i].next) {
            v = edges[i].v;
            if(dist[v] == dist[u] + 1 && edges[i].capacity > 0) {
                pushed = send_flow(v, min(flow - total_flow, edges[i].capacity));
