        }
        if(total_flow == 0) dist[u] = -1;
        return total_flow;
    }

    int max_flow(int s, int t) {
        source = s; sink = t;
        int total_flow = 0;
        while(build_bfs()) {
            total_flow += send_flow(s, INT_MAX);
        }
        return total_flow;
    }
};

