import java.util.*;
import java.io.*;

public class MaxFlowSolver {
    static final int INF = 1000000000;
    static int n, T;
    static char[][] grid = new char[15][15];
    static char[][] capsule = new char[15][15];
    static int[][] Z = new int[15][15];
    static int[][] S = new int[15][15];
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};
    static int sourceNode, sinkNode;
    static MaxFlow flow;

    static class Edge {
        int v, capacity, next;
        Edge(int v, int capacity, int next) {
            this.v = v;
            this.capacity = capacity;
            this.next = next;
        }
    }

    static class MaxFlow {
        int[] head;
        List<Edge> edges;
        int total;

        MaxFlow(int size) {
            head = new int[size];
            Arrays.fill(head, -1);
            edges = new ArrayList<>();
            total = 0;
        }

        void addEdge(int u, int v, int cap) {
            edges.add(new Edge(v, cap, head[u]));
            head[u] = total++;
            edges.add(new Edge(u, 0, head[v]));
            head[v] = total++;
        }

        void initialize() {
            Arrays.fill(head, -1);
            edges.clear();
            total = 0;
        }

        int buildBFS(int s, int t, int[] dist, int[] current) {
            Arrays.fill(dist, -1);
            System.arraycopy(head, 0, current, 0, head.length);
            dist[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int i = head[u]; i != -1; i = edges.get(i).next) {
                    int v = edges.get(i).v;
                    if (dist[v] == -1 && edges.get(i).capacity > 0) {
                        dist[v] = dist[u] + 1;
                        q.offer(v);
                    }
                }
            }
            return dist[t] != -1 ? 1 : 0;
        }

        int sendFlow(int u, int t, int flow, int[] dist, int[] current) {
            if (u == t) return flow;
            int totalFlow = 0;
            for (int i = current[u]; i != -1; i = edges.get(i).next) {
                int v = edges.get(i).v;
                if (dist[v] == dist[u] + 1 && edges.get(i).capacity > 0) {
                    int pushed = sendFlow(v, t, Math.min(flow - totalFlow, edges.get(i).capacity), dist, current);
                    if (pushed > 0) {
                        edges.get(i).capacity -= pushed;
                        edges.get(i ^ 1).capacity += pushed;
                        totalFlow += pushed;
                        if (totalFlow == flow) break;
                    }
                }
                current[u]++;
            }
            if (totalFlow == 0) dist[u] = -1;
            return totalFlow;
        }

        int maxFlow(int s, int t) {
            int totalFlow = 0;
            int[] dist = new int[head.length];
            int[] current = new int[head.length];
            while (buildBFS(s, t, dist, current) != 0) {
                Arrays.fill(current, 0);
                totalFlow += sendFlow(s, t, INF, dist, current);
            }
            return totalFlow;
        }
    }

    static boolean inside(int i, int j) {
        return i >= 0 && i < n && j >= 0 && j < n;
    }

    static boolean isDigit(char ch) {
        return ch >= '1' && ch <= '9';
    }

    static void performBFS(int x, int y, int[][] distMap, boolean mark) {
        int startX = x, startY = y;
        for (int[] row : distMap) {
            Arrays.fill(row, 0x3f3f3f3f);
        }
        distMap[x][y] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(x);
        q.offer(y);
        if (mark && isDigit(capsule[x][y])) {
            flow.addEdge(startX * n + startY, startX * n + startY + n * n, INF);
        }
        while (!q.isEmpty()) {
            int cx = q.poll();
            int cy = q.poll();
            if (distMap[cx][cy] == T) break;
            for (int o = 0; o < 4; o++) {
                int xx = cx + dx[o];
                int yy = cy + dy[o];
                if (inside(xx, yy) && distMap[xx][yy] == 0x3f3f3f3f && capsule[xx][yy] != 'Y') {
                    if (Z[xx][yy] > distMap[cx][cy] + 1 || (Z[xx][yy] == distMap[cx][cy] + 1 && isDigit(capsule[xx][yy]))) {
                        distMap[xx][yy] = distMap[cx][cy] + 1;
                        if (mark && isDigit(capsule[xx][yy])) {
                            flow.addEdge(startX * n + startY, xx * n + yy + n * n, INF);
                        }
                        if (Z[xx][yy] > distMap[cx][cy] + 1 || !mark) {
                            q.offer(xx);
                            q.offer(yy);
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());
        flow = new MaxFlow(210);
        int x = -1, y = -1;
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            grid[i] = line.toCharArray();
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'Z') {
                    x = i;
                    y = j;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            capsule[i] = line.toCharArray();
            for (int j = 0; j < n; j++) {
                if (isDigit(capsule[i][j])) {
                    flow.addEdge(i * n + j + n * n, n * n * 2 + 1, capsule[i][j] - '0');
                }
            }
        }
        int[][] ZMap = new int[n][n];
        performBFS(x, y, ZMap, false);
        int source_node = n * n * 2;
        int sink_node = source_node + 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (isDigit(grid[i][j])) {
                    flow.addEdge(source_node, i * n + j, grid[i][j] - '0');
                    int[][] SMap = new int[n][n];
                    performBFS(i, j, SMap, true);
                }
            }
        }
        System.out.println(flow.maxFlow(source_node, sink_node));
    }
}
